# Link Link ## Использование Использование ```tsx
import React from 'react';
import { TextS, Link } from '@salutejs/sdds-finai';

export function App() {
    return (
        <TextS>
            Скачайте <Link href="/" target="_blank">приложение.</Link>
        </TextS>
    );
}
```

## Примеры Примеры ### Подчёркивание Подчёркивание Prop  `underline`  управляет режимом подчёркивания ссылки: `none`  — без подчёркивания (по умолчанию) `hover`  — подчёркивание при наведении `always`  — всегда подчёркнута ```tsx
import React from 'react';
import { TextS, Link } from '@salutejs/sdds-finai';

export function App() {
    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
            <TextS><Link href="/" underline="none">Без подчёркивания</Link></TextS>
            <TextS><Link href="/" underline="hover">Подчёркивание при наведении</Link></TextS>
            <TextS><Link href="/" underline="always">Всегда подчёркнута</Link></TextS>
        </div>
    );
}
```
